{"Table":"bk_tb_transactions","Create Table":"CREATE TABLE `bk_tb_transactions` (\n  `id` varchar(36) NOT NULL,\n  `description` varchar(255) NOT NULL,\n  `value` double NOT NULL,\n  `owner` varchar(255) NOT NULL,\n  `category` varchar(255) NOT NULL,\n  `account` varchar(255) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `date` timestamp NOT NULL DEFAULT current_timestamp(),\n  `batch_id` varchar(255) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `FK_transaction_owner` (`owner`),\n  KEY `idx_account_category` (`account`,`category`),\n  KEY `idx_category_date_value` (`category`,`date` DESC,`value`),\n  KEY `idx_transaction_account` (`account`),\n  KEY `idx_transaction_category` (`category`),\n  CONSTRAINT `FK_transaction_account` FOREIGN KEY (`account`) REFERENCES `bk_tb_accounts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `FK_transaction_category` FOREIGN KEY (`category`) REFERENCES `bk_tb_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `FK_transaction_owner` FOREIGN KEY (`owner`) REFERENCES `bk_tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"bk_tb_transactions.sql","path":"files/sql/rod/bk_tb_transactions.sql","sha":"c963213e4d4711e8956b31d9c270580d1a643c6f","size":173483,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/bk_tb_transactions.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/bk_tb_transactions.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/c963213e4d4711e8956b31d9c270580d1a643c6f","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/bk_tb_transactions.sql","type":"file","content":"eyJUYWJsZSI6ImJrX3RiX3RyYW5zYWN0aW9ucyIsIkNyZWF0ZSBUYWJsZSI6\nIkNSRUFURSBUQUJMRSBgYmtfdGJfdHJhbn